import json
res=[]
for line in open('journal.jsonl'):
    try: r=json.loads(line)
    except: continue
    if r.get('type')=='result': res.append(r.get('value'))
out=[]
for v in res:
    if isinstance(v,dict) and 'surviving_summary' in v:
        out.append('#'*70)
        out.append('CORRECTED: '+v['surviving_summary'])
        out.append('REFUTED %d:'%len(v.get('refuted_claims',[])))
        for rc in v.get('refuted_claims',[]):
            out.append(' - CLAIM: '+rc['claim'][:260])
            out.append('   WHY: '+rc['why_wrong'][:380])
            out.append('   FIX: '+rc['correct_version'][:380])
print(chr(10).join(out))

